import React from 'react';

const TestimonialsSection = () => {
    const testimonials = [
        {
            name: "Michael B.",
            rating: 5,
            text: "I finally feel heard in meetings. My confidence has skyrocketed.",
            image: "https://randomuser.me/api/portraits/men/32.jpg"
        },
        {
            name: "Emily R.",
            rating: 5,
            text: "The feedback exercises were a game-changer. Highly recommend this.",
            image: "https://randomuser.me/api/portraits/women/44.jpg"
        },
        {
            name: "Daniel G.",
            rating: 5,
            text: "My vocal strain is gone, and my delivery is so much more impactful.",
            image: "https://randomuser.me/api/portraits/men/85.jpg"
        },
        {
            name: "Chris L.",
            rating: 5,
            text: "A truly transformative experience. My voice is rich and resonant.",
            image: "https://randomuser.me/api/portraits/men/22.jpg"
        }
    ];

    const StarRating = ({ rating }) => {
        return (
            <div className="flex gap-0.5">
                {[...Array(rating)].map((_, i) => (
                    <svg key={i} className="w-4 h-4 text-[#FFC107]" fill="currentColor" viewBox="0 0 20 20">
                        <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                    </svg>
                ))}
            </div>
        );
    };

    return (
        <section className="bg-[#EFF9F0] w-full py-[60px] md:py-[100px] border-y border-[#E5E7EB] overflow-hidden">
            <div className="container mx-auto max-w-[1446px] px-6 md:px-[104px]">
                <div className="text-center mb-[40px] md:mb-[60px]">
                    <h2 className="font-serif text-[32px] md:text-[54px] font-bold text-[#212529] mb-3 md:mb-5 leading-tight">
                        Transforming Lives <span className="text-guarantee-green">Worldwide</span>
                    </h2>
                    <p className="font-poppins text-gray-text text-sm md:text-xl md:leading-[30px] opacity-80">
                        Real stories from readers who found freedom
                    </p>
                </div>

                <div className="flex flex-nowrap md:flex-wrap overflow-x-auto md:overflow-x-visible pb-8 md:pb-0 gap-[30px] justify-start md:justify-center scrollbar-hide">
                    {testimonials.map((item, index) => (
                        <div
                            key={index}
                            className="bg-white rounded-[24px] shadow-[0_10px_30px_rgba(0,0,0,0.04)] p-6 md:p-8 min-w-[280px] md:min-w-[320px] max-w-[340px] flex flex-col gap-5 hover:translate-y-[-5px] transition-transform duration-300 border border-white/50"
                        >
                            <div className="flex items-center gap-4">
                                <div className="w-[60px] h-[60px] rounded-full overflow-hidden border-2 border-guarantee-green/10">
                                    <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                                </div>
                                <div className="flex flex-col gap-1">
                                    <h4 className="font-sans font-bold text-[#212529] text-lg">{item.name}</h4>
                                    <StarRating rating={item.rating} />
                                </div>
                            </div>
                            <p className="font-poppins text-[#495057] text-sm md:text-base leading-relaxed italic">
                                "{item.text}"
                            </p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default TestimonialsSection;
